label.source:
// A short label in the work's type with a paper-coloured halo, so it stays legible over
// pictures and lines. Lines break at "\n"; an optional note sits underneath, smaller.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const size = Number(d.size ?? 16);
const align = d.align ?? "center";
const x = align === "start" ? 0 : align === "end" ? W : W / 2;
const anchor = align === "center" ? "middle" : align;
const esc = (s) =>
  String(s).replace(
    /[&<>"]/g,
    (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch],
  );
const lines = String(d.text ?? "").split("\n");
const note = d.note ? String(d.note).split("\n") : [];
const noteSize = size * 0.78;
const total = lines.length * size * 1.25 + note.length * noteSize * 1.3;
let y = (H - total) / 2 + size * 0.95;
const halo =
  d.halo === false
    ? ""
    : `paint-order="stroke" stroke="${t.paper || "#fff"}" stroke-width="${Math.max(3, size / 4)}" stroke-linejoin="round"`;
const rows = [];
for (const line of lines) {
  rows.push(
    `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}" font-weight="${d.weight ?? 500}" fill="${d.color || t.ink || "#222"}" ${halo}>${esc(line)}</text>`,
  );
  y += size * 1.25;
}
for (const line of note) {
  rows.push(
    `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${noteSize}" fill="${d.noteColor || t.muted || "#777"}" ${halo}>${esc(line)}</text>`,
  );
  y += noteSize * 1.3;
}
return api.svg(
  `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="overflow:visible" font-family="${esc(t.font || "system-ui")}">${rows.join("")}</svg>`,
);

sky.source:
// 夜空：从深蓝到海平线的一抹暖光，星星各按各的节奏闪，一道淡淡的银河，
// 带光晕的月亮，远处岬角上还有一座小灯塔，按自己的灯质一闪一闪。
const { width: w, height: h, data: d } = api;
const H = h * d.horizon;
let seed = 11;
const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;

const stars = [];
for (let i = 0; i < d.stars; i++) {
  const x = rnd() * w,
    y = Math.pow(rnd(), 1.5) * H * 0.9;
  const big = rnd() < 0.07;
  stars.push({ x, y, r: big ? 1.5 + rnd() * 0.8 : 0.45 + rnd() * 0.85, p: rnd() * 6.28, f: 0.5 + rnd() * 1.8, big });
}
// 银河：沿一条斜线撒很多极小的点
const dust = [];
for (let i = 0; i < 520; i++) {
  const u = rnd(),
    v = (rnd() + rnd() + rnd() - 1.5) * 0.55;
  const x = w * (0.18 + u * 0.78),
    y = H * (0.92 - u * 0.86) + v * 70;
  if (y > 0 && y < H * 0.95) dust.push(`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${(0.3 + rnd() * 0.55).toFixed(2)}"/>`);
}
const [mx, my, mr] = [d.moon[0] * w, d.moon[1] * h, d.moonSize];
// 远处岬角：一条低矮起伏的剪影
const land = [];
for (let x = 0; x <= w * 0.42; x += 12) {
  const y = H - 6 - 20 * Math.exp(-(((x - w * 0.12) / 120) ** 2)) - 9 * Math.sin(x / 37) * Math.exp(-x / 260) - 14 * Math.exp(-(((x - w * 0.3) / 60) ** 2));
  land.push(`${x.toFixed(0)} ${y.toFixed(1)}`);
}
const far = [w * 0.297, H - 22];

const svg = api.svg(`<svg viewBox="0 0 ${w} ${h}" width="${w}" height="${h}">
  <defs>
    <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="${d.top}"/>
      <stop offset=".5" stop-color="${d.middle}"/>
      <stop offset=".86" stop-color="${d.bottom}"/>
      <stop offset="1" stop-color="${d.dusk}"/>
    </linearGradient>
    <radialGradient id="halo"><stop offset="0" stop-color="#e9efff" stop-opacity=".55"/><stop offset=".25" stop-color="#c4d0f5" stop-opacity=".22"/><stop offset="1" stop-color="#9fb2ea" stop-opacity="0"/></radialGradient>
    <radialGradient id="moon" cx=".4" cy=".38"><stop offset="0" stop-color="#fffdf3"/><stop offset=".7" stop-color="#f0ecdc"/><stop offset="1" stop-color="#d9d6c8"/></radialGradient>
    <radialGradient id="mw" cx=".5" cy=".5" r=".5"><stop offset="0" stop-color="#b9c6f0" stop-opacity=".16"/><stop offset="1" stop-color="#b9c6f0" stop-opacity="0"/></radialGradient>
    <radialGradient id="spark"><stop offset="0" stop-color="#fff6d8"/><stop offset=".3" stop-color="#ffd98a" stop-opacity=".6"/><stop offset="1" stop-color="#ffd98a" stop-opacity="0"/></radialGradient>
  </defs>
  <rect width="${w}" height="${h}" fill="url(#sky)"/>
  <ellipse cx="${w * 0.6}" cy="${H * 0.5}" rx="${w * 0.5}" ry="70" fill="url(#mw)" transform="rotate(-24 ${w * 0.6} ${H * 0.5})"/>
  <g fill="#dfe6ff" opacity=".55">${dust.join("")}</g>
  <g class="stars"></g>
  <circle cx="${mx}" cy="${my}" r="${mr * 5}" fill="url(#halo)"/>
  <circle cx="${mx}" cy="${my}" r="${mr}" fill="url(#moon)"/>
  <g fill="#b9b39f" opacity=".28">
    <circle cx="${mx - mr * 0.3}" cy="${my - mr * 0.2}" r="${mr * 0.22}"/>
    <circle cx="${mx + mr * 0.28}" cy="${my + mr * 0.25}" r="${mr * 0.16}"/>
    <circle cx="${mx + mr * 0.1}" cy="${my - mr * 0.45}" r="${mr * 0.1}"/>
    <circle cx="${mx - mr * 0.42}" cy="${my + mr * 0.35}" r="${mr * 0.09}"/>
  </g>
  <path d="M0 ${H} L${land.join(" L")} L${w * 0.42} ${H} Z" fill="${d.land}"/>
  <rect x="${far[0] - 1.6}" y="${far[1] - 9}" width="3.2" height="10" fill="#2a3560"/>
  <circle class="far" cx="${far[0]}" cy="${far[1] - 10}" r="16" fill="url(#spark)"/>
</svg>`);

const group = svg.querySelector(".stars");
const dots = stars.map((s) => {
  const g = document.createElementNS("http://www.w3.org/2000/svg", "g");
  g.setAttribute("transform", `translate(${s.x.toFixed(1)} ${s.y.toFixed(1)})`);
  g.innerHTML = s.big
    ? `<circle r="${s.r}" fill="#fff"/><path d="M-${s.r * 5} 0H${s.r * 5}M0 -${s.r * 5}V${s.r * 5}" stroke="#e8eeff" stroke-width=".6" opacity=".7"/>`
    : `<circle r="${s.r}" fill="#f3f5ff"/>`;
  group.append(g);
  return g;
});
const farLight = svg.querySelector(".far");
// 远处那座灯塔：每 6 秒连闪两下
const flash = (t) => {
  const p = t % 6;
  return Math.max(Math.exp(-(((p - 0.4) / 0.12) ** 2)), Math.exp(-(((p - 1.3) / 0.12) ** 2)));
};
api.animate(() => {
  const t = performance.now() / 1000;
  dots.forEach((g, i) => {
    const s = stars[i];
    g.setAttribute("opacity", (0.45 + 0.55 * Math.abs(Math.sin(t * s.f * 0.6 + s.p))).toFixed(2));
  });
  const f = flash(t);
  farLight.setAttribute("opacity", (0.12 + 0.88 * f).toFixed(2));
  farLight.setAttribute("r", (6 + 12 * f).toFixed(1));
});
return svg;

sea.source:
// 夜里的海：越近浪越大，一排排浪尖带着月光；月亮和灯塔各在海面上拖出一条碎光，
// 灯塔那条跟着光束转——光正对着我们时，它最亮。
const { width: w, height: h, data: d } = api;
const rows = d.rows;
let seed = 5;
const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
const glints = (x0, color, n, spread) =>
  Array.from({ length: n }, () => {
    const v = rnd() ** 1.25;
    const y = 4 + v * (h - 10);
    const half = spread * (0.25 + v * 1.2) * (0.5 + rnd());
    const x = x0 + (rnd() - 0.5) * spread * (0.6 + v * 2.4);
    return { x, y, half, p: rnd() * 6.28, f: 0.8 + rnd() * 1.6, color };
  });
const moon = glints(d.moonX, "#dfe6ff", 70, 26);
const lamp = glints(d.lampX, "#ffd88f", 90, 22);

const svg = api.svg(`<svg viewBox="0 0 ${w} ${h}" width="${w}" height="${h}">
  <defs>
    <linearGradient id="sea" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="${d.near}"/><stop offset=".05" stop-color="${d.top}"/><stop offset="1" stop-color="${d.bottom}"/>
    </linearGradient>
  </defs>
  <rect width="${w}" height="${h}" fill="url(#sea)"/>
  <g class="waves" fill="none" stroke-linecap="round"></g>
  <g class="moon"></g>
  <g class="lamp"></g>
</svg>`);
const waves = svg.querySelector(".waves");
const paths = Array.from({ length: rows }, (_, j) => {
  const p = document.createElementNS("http://www.w3.org/2000/svg", "path");
  const v = (j + 1) / rows;
  p.setAttribute("stroke", j % 3 === 0 ? "#8ea3dc" : "#5d70ad");
  p.setAttribute("stroke-width", (0.6 + v * 2.2).toFixed(2));
  p.setAttribute("opacity", (0.18 + v * 0.45).toFixed(2));
  p.setAttribute("stroke-dasharray", `${(30 + v * 140).toFixed(0)} ${(20 + v * 90).toFixed(0)}`);
  waves.append(p);
  return p;
});
const strokes = (group, list) =>
  list.map((g) => {
    const l = document.createElementNS("http://www.w3.org/2000/svg", "line");
    l.setAttribute("stroke", g.color);
    l.setAttribute("stroke-linecap", "round");
    l.setAttribute("stroke-width", (1 + (g.y / h) * 2.2).toFixed(2));
    group.append(l);
    return l;
  });
const moonLines = strokes(svg.querySelector(".moon"), moon);
const lampLines = strokes(svg.querySelector(".lamp"), lamp);
api.animate(() => {
  const t = performance.now() / 1000;
  paths.forEach((p, j) => {
    const v = (j + 1) / rows;
    const y0 = 3 + (h - 6) * v ** 1.8;
    const len = 60 + v * 260,
      amp = 1 + v * 7,
      sp = (j % 2 ? 1 : -1) * (6 + v * 18);
    let s = "";
    for (let x = -20; x <= w + 20; x += 16) {
      const y = y0 + amp * Math.sin((x + t * sp) / len * 6.28 + j * 1.7);
      s += (s ? "L" : "M") + x.toFixed(0) + " " + y.toFixed(1);
    }
    p.setAttribute("d", s);
    p.setAttribute("stroke-dashoffset", (t * sp * 2).toFixed(1));
  });
  // 灯塔的两束光背对背转，一圈 period 秒；朝向我们时海面上的倒影最亮
  const c = Math.cos((2 * Math.PI * t) / d.period);
  const facing = Math.max(c, -c) ** 10;
  const shimmer = (lines, list, gain) =>
    lines.forEach((l, i) => {
      const g = list[i];
      const wob = Math.sin(t * g.f + g.p);
      const half = g.half * (0.6 + 0.4 * wob);
      l.setAttribute("x1", (g.x - half).toFixed(1));
      l.setAttribute("x2", (g.x + half).toFixed(1));
      l.setAttribute("y1", g.y.toFixed(1));
      l.setAttribute("y2", g.y.toFixed(1));
      l.setAttribute("opacity", Math.max(0, (0.15 + 0.85 * Math.max(0, wob)) * gain * (1 - (g.y / h) * 0.35)).toFixed(2));
    });
  shimmer(moonLines, moon, 0.75);
  shimmer(lampLines, lamp, 0.35 + 0.65 * facing);
});
return svg;

lighthouse.source:
// 夜里的灯塔：礁石、守塔人的小屋、红白相间的塔身被月光从左边照亮，灯室里的透镜在转。
// 两束光背对背绕着塔转：侧着看是长长的光柱，转到正对我们时变成一团刺眼的闪光。
const { width: w, height: h, data: d } = api;
const cx = w / 2,
  lampY = d.lamp * h;
// 礁石的轮廓：几块起伏叠在一起，塔立在最高的那块上
const wl = h - d.waterline;
const hump = (x) =>
  70 * Math.exp(-(((x - cx - 6) / 64) ** 2)) + 44 * Math.exp(-(((x - 74) / 48) ** 2)) + 30 * Math.exp(-(((x - w + 62) / 40) ** 2)) + 12 * Math.exp(-(((x - w + 20) / 16) ** 2)) + 10 * Math.exp(-(((x - 18) / 18) ** 2));
const jag = (x) => 2.4 * Math.sin(x * 0.21) + 1.6 * Math.sin(x * 0.53 + 1) + 0.8 * Math.sin(x * 1.7);
const ridgePts = [];
for (let x = 2; x <= w - 2; x += 5) ridgePts.push([x, wl - Math.max(0, hump(x) + jag(x) * Math.min(1, hump(x) / 10))]);
const ground = (x) => wl - hump(x) + 3;
const base = ground(cx),
  top = lampY + 40;
const bw = 34,
  tw = 21;
const at = (y) => bw + (tw - bw) * ((base - y) / (base - top)) ** 0.9;
const side = (sgn) => {
  const pts = [];
  for (let i = 0; i <= 12; i++) {
    const y = base - ((base - top) * i) / 12;
    pts.push(`${(cx + sgn * at(y)).toFixed(1)} ${y.toFixed(1)}`);
  }
  return pts;
};
const line = (pts) => pts.map(([x, y]) => `${x.toFixed(1)} ${y.toFixed(1)}`).join(" L");
const rocks = `M2 ${wl} L${line(ridgePts)} L${w - 2} ${wl} Z`;
const ridge = `M${line(ridgePts)}`;
const mirror = `M2 ${wl} L${line(ridgePts.map(([x, y]) => [x, wl + (wl - y) * 0.7]))} L${w - 2} ${wl} Z`;
// 礁石上的裂纹和背光的一面
const cracks = [
  [cx - 30, 0.55, -14, 22],
  [cx + 26, 0.45, 10, 18],
  [70, 0.5, -8, 16],
  [w - 64, 0.5, 9, 12],
  [cx - 70, 0.3, 6, 10],
]
  .map(([x, f, dx, len]) => {
    const y = wl - hump(x) * f;
    return `M${x} ${y.toFixed(1)} l${dx * 0.5} ${len * 0.5} l${dx * 0.3} ${len * 0.6}`;
  })
  .join(" ");
const house = { x: 76, y: ground(76) };
const tower = `M${side(-1).join(" L")} L${side(1).reverse().join(" L")} Z`;
const bands = [0.2, 0.5, 0.8]
  .map((f) => {
    const y = base - (base - top) * f;
    return `<rect x="${cx - 40}" y="${(y - 15).toFixed(1)}" width="80" height="28"/>`;
  })
  .join("");
const svg = api.svg(`<svg viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" style="overflow:visible">
  <defs>
    <linearGradient id="wall" x1="0" x2="1"><stop offset="0" stop-color="#e6e9f5"/><stop offset=".45" stop-color="#b5bcd6"/><stop offset="1" stop-color="#4c5475"/></linearGradient>
    <linearGradient id="red" x1="0" x2="1"><stop offset="0" stop-color="#b0474f"/><stop offset=".5" stop-color="#83303b"/><stop offset="1" stop-color="#3b1d2b"/></linearGradient>
    <linearGradient id="rock" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#3a4672"/><stop offset=".45" stop-color="#1f2747"/><stop offset="1" stop-color="#080c1d"/></linearGradient>
    <radialGradient id="glow"><stop offset="0" stop-color="#fffbe8" stop-opacity="1"/><stop offset=".12" stop-color="#ffe7a6" stop-opacity=".75"/><stop offset=".4" stop-color="#ffcf73" stop-opacity=".22"/><stop offset="1" stop-color="#ffcf73" stop-opacity="0"/></radialGradient>
    <linearGradient id="b0" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#fff3cf" stop-opacity=".8"/><stop offset=".35" stop-color="#ffe7a8" stop-opacity=".32"/><stop offset="1" stop-color="#ffe7a8" stop-opacity="0"/></linearGradient>
    <linearGradient id="b1" gradientUnits="userSpaceOnUse"><stop offset="0" stop-color="#fff3cf" stop-opacity=".8"/><stop offset=".35" stop-color="#ffe7a8" stop-opacity=".32"/><stop offset="1" stop-color="#ffe7a8" stop-opacity="0"/></linearGradient>
    <clipPath id="clip"><path d="${tower}"/></clipPath>
    <clipPath id="frame"><rect x="${d.frame[0]}" y="${d.frame[1]}" width="${d.frame[2]}" height="${d.frame[3]}"/></clipPath>
    <linearGradient id="mirror" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#0b1026" stop-opacity=".85"/><stop offset="1" stop-color="#0b1026" stop-opacity="0"/></linearGradient>
    <linearGradient id="rim" gradientUnits="userSpaceOnUse" x1="0" x2="${w}"><stop offset="0" stop-color="#ffd79a" stop-opacity=".15"/><stop offset=".5" stop-color="#ffd79a" stop-opacity=".7"/><stop offset="1" stop-color="#ffd79a" stop-opacity=".2"/></linearGradient>
    <radialGradient id="lens" cx=".5" cy=".55" r=".6"><stop offset="0" stop-color="#fffdf0"/><stop offset=".45" stop-color="#ffe7a2"/><stop offset="1" stop-color="#e9a94a"/></radialGradient>
  </defs>
  <g class="beams" clip-path="url(#frame)">
    <path class="beam" fill="url(#b0)"/><path class="beam core" fill="url(#b0)"/>
    <path class="beam" fill="url(#b1)"/><path class="beam core" fill="url(#b1)"/>
  </g>
  <path d="${mirror}" fill="url(#mirror)"/>
  <path d="${rocks}" fill="url(#rock)"/>
  <path d="${cracks}" fill="none" stroke="#070b1a" stroke-width="2" stroke-linecap="round" opacity=".8"/>
  <path d="${ridge}" fill="none" stroke="url(#rim)" stroke-width="2.2" stroke-linejoin="round"/>
  <g>
    <path d="M${house.x - 32} ${house.y + 6} V${house.y - 28} L${house.x} ${house.y - 50} L${house.x + 32} ${house.y - 28} V${house.y + 6} Z" fill="#c7cce0"/>
    <path d="M${house.x} ${house.y - 50} L${house.x + 32} ${house.y - 28} V${house.y + 6} H${house.x} Z" fill="#59617f" opacity=".75"/>
    <path d="M${house.x - 38} ${house.y - 26} L${house.x} ${house.y - 54} L${house.x + 38} ${house.y - 26}" fill="none" stroke="#3a2230" stroke-width="7" stroke-linejoin="round"/>
    <rect x="${house.x - 22}" y="${house.y - 20}" width="12" height="14" fill="#ffcf7a"/>
    <rect x="${house.x - 22}" y="${house.y - 20}" width="12" height="14" fill="none" stroke="#3a2a2a" stroke-width="1.5"/>
    <rect x="${house.x + 10}" y="${house.y - 20}" width="12" height="14" fill="#ffd98f" opacity=".85"/>
    <circle cx="${house.x - 16}" cy="${house.y - 13}" r="22" fill="url(#glow)" opacity=".5"/>
  </g>
  <path d="${tower}" fill="url(#wall)"/>
  <g clip-path="url(#clip)" fill="url(#red)">${bands}</g>
  <g fill="#1d2338">
    <rect x="${cx - 4}" y="${base - 28}" width="8" height="20" rx="4"/>
    <rect x="${cx - 3}" y="${base - (base - top) * 0.36 - 8}" width="6" height="11" rx="3" fill="#ffd27a" opacity=".85"/>
    <rect x="${cx - 3}" y="${base - (base - top) * 0.66 - 8}" width="6" height="11" rx="3"/>
  </g>
  <rect x="${cx - tw - 8}" y="${top - 6}" width="${(tw + 8) * 2}" height="6" fill="#2a2f45"/>
  <path d="M${cx - tw - 6} ${top - 6} V${top - 17} H${cx + tw + 6} V${top - 6} M${cx - tw} ${top - 6} V${top - 16} M${cx - 8} ${top - 6} V${top - 16} M${cx + 8} ${top - 6} V${top - 16} M${cx + tw} ${top - 6} V${top - 16}" stroke="#2a2f45" stroke-width="1.6" fill="none"/>
  <rect x="${cx - 15}" y="${lampY - 18}" width="30" height="${top - lampY + 12}" fill="url(#lens)"/>
  <path d="M${cx - 15} ${lampY - 18} V${top - 6} M${cx - 5} ${lampY - 18} V${top - 6} M${cx + 5} ${lampY - 18} V${top - 6} M${cx + 15} ${lampY - 18} V${top - 6} M${cx - 15} ${lampY + 4} H${cx + 15}" stroke="#3a3346" stroke-width="1.4" opacity=".55"/>
  <path d="M${cx - 19} ${lampY - 18} Q${cx} ${lampY - 44} ${cx + 19} ${lampY - 18} Z" fill="#262c45"/>
  <path d="M${cx} ${lampY - 38} V${lampY - 56}" stroke="#262c45" stroke-width="2"/><circle cx="${cx}" cy="${lampY - 37}" r="3.4" fill="#262c45"/>
  <circle class="glow" cx="${cx}" cy="${lampY}" r="120" fill="url(#glow)"/>
  <g class="flare" opacity="0">
    <circle cx="${cx}" cy="${lampY}" r="260" fill="url(#glow)"/>
    <path d="M${cx - 150} ${lampY} H${cx + 150} M${cx} ${lampY - 70} V${lampY + 70}" stroke="#fff6dc" stroke-width="1.6" opacity=".7"/>
  </g>
  <circle cx="${cx}" cy="${lampY}" r="5" fill="#fffdf2"/>
  <g class="foam" fill="none" stroke="#dfe7ff" stroke-linecap="round"></g>
</svg>`);

const beams = [...svg.querySelectorAll(".beam")];
const grads = [svg.querySelector("#b0"), svg.querySelector("#b1")];
const glow = svg.querySelector(".glow"),
  flare = svg.querySelector(".flare"),
  foam = svg.querySelector(".foam");
const L = d.reach;
api.animate(() => {
  const t = performance.now() / 1000;
  const th = (2 * Math.PI * t) / d.period;
  let facing = 0;
  for (let k = 0; k < 2; k++) {
    const a = th + k * Math.PI;
    const s = Math.sin(a),
      c = Math.cos(a);
    facing = Math.max(facing, c > 0 ? c ** 14 : 0);
    const dir = s >= 0 ? 1 : -1,
      len = 30 + L * Math.abs(s) ** 0.7;
    const spread = 6 + 46 * Math.abs(s) + 60 * Math.max(0, c);
    const ex = cx + dir * len;
    // 光柱：近处窄、远处宽，向后的那一束淡一些
    const fade = (0.35 + 0.65 * Math.abs(s)) * (c < 0 ? 0.75 : 1);
    beams[k * 2].setAttribute("d", `M${cx} ${lampY - 7} L${ex} ${lampY - spread} L${ex} ${lampY + spread * 0.55} L${cx} ${lampY + 7} Z`);
    beams[k * 2 + 1].setAttribute("d", `M${cx} ${lampY - 4} L${ex} ${lampY - spread * 0.42} L${ex} ${lampY + spread * 0.18} L${cx} ${lampY + 4} Z`);
    beams[k * 2].setAttribute("opacity", (0.55 * fade).toFixed(3));
    beams[k * 2 + 1].setAttribute("opacity", (0.8 * fade).toFixed(3));
    grads[k].setAttribute("x1", cx);
    grads[k].setAttribute("x2", ex);
    grads[k].setAttribute("y1", lampY);
    grads[k].setAttribute("y2", lampY);
  }
  flare.setAttribute("opacity", facing.toFixed(3));
  glow.setAttribute("r", (110 + 40 * facing).toFixed(1));
  // 浪一阵一阵拍上礁石，水线上的白沫跟着涨落
  const p = (t % 3.6) / 3.6;
  foam.innerHTML = [
    [10, 46, 0],
    [w - 60, 52, 0.35],
    [cx - 40, 70, 0.62],
    [cx + 60, 40, 0.15],
  ]
    .map(([x, r, off]) => {
      const q = Math.max(0, Math.sin(Math.PI * ((p + off) % 1)));
      const y = wl - 2 - 6 * q;
      return `<path d="M${x} ${wl} q${r * 0.25} ${-12 * q - 2} ${r * 0.5} ${-4 * q} t${r * 0.5} ${-3 * q}" stroke-width="${1.4 + 2.2 * q}" opacity="${(0.2 + 0.65 * q).toFixed(2)}"/><path d="M${x - 6} ${wl + 3} h${r + 12}" stroke-width="1.2" opacity="${(0.15 + 0.3 * q).toFixed(2)}"/>`;
    })
    .join("");
});
return svg;

